#define LPT1_DATA_PORT 0x378
#define BYTE_TO_WRITE 0x55

// Variables defined based on function signature
unsigned char output_data = BYTE_TO_WRITE;
unsigned short target_port = LPT1_DATA_PORT;

// Write byte to port, ensuring execution pause
// (requires prior ioperm() or iopl() setup)
outb_p(output_data, target_port);

// Direct usage example
outb_p(0x0A, 0x3C4); // Write 0x0A to VGA Sequence Controller Index Port
outb_p(0x80, 0x00);  // Write 0x80 to Port 0 (unused dummy port)
outb_p(0x00, 0x00);  // Used internally as a general pause instruction
